CURLcode smtp_escape_eob(struct connectdata *conn, ssize_t nread) {
  char *scratch = NULL;
  char *src, *dst;
  size_t i = 0;
  size_t replacements = 0;
  ssize_t scratch_len = nread;
  CURLcode result = CURLE_OK;

  scratch = malloc(nread + 1);
  if (!scratch) {
    return CURLE_OUT_OF_MEMORY;
  }

  src = conn->uploadbuf;
  dst = scratch;

  while (i < nread - 1) {
    if (src[i] == '\r' && src[i + 1] == '\n') {
      *dst++ = '.';
      replacements++;
      i += 2;
    } else {
      *dst++ = src[i++];
    }
  }

  if (i < nread) {
    *dst++ = src[i];
  }

  *dst = '\0';

  if (replacements > 0) {
    free(conn->uploadbuf);
    conn->uploadbuf = scratch;
    scratch = NULL;
    conn->upload_size = dst - scratch;
    conn->upload_left = conn->upload_size;
  } else {
    free(scratch);
  }

  return result;
}

CURLcode smtp_escape_eob(struct connectdata *conn, ssize_t nread) {
  char *scratch = NULL;
  size_t i = 0, j = 0;
  size_t original_len = nread;
  size_t scratch_len = 0;
  bool trailing_crlf = FALSE;
  CURLcode result = CURLE_OK;
  size_t replacements = 0;

  scratch = malloc(original_len + 2);  // Max possible expansion is adding 2 bytes (CRLF -> CRLFCRLF)
  if (!scratch) {
    return CURLE_OUT_OF_MEMORY;
  }

  for (i = 0; i < original_len; i++) {
    if (i + 1 < original_len && conn->uploadfromhere[i] == '\r' &&
        conn->uploadfromhere[i + 1] == '\n') {
      scratch[j++] = '\r';
      scratch[j++] = '\n';
      scratch[j++] = '\r';
      scratch[j++] = '\n';
      i++;
      replacements++;
    } else {
      scratch[j++] = conn->uploadfromhere[i];
    }
  }

  // Check for trailing CRLF
  if (original_len >= 2 &&
      conn->uploadfromhere[original_len - 2] == '\r' &&
      conn->uploadfromhere[original_len - 1] == '\n') {
    trailing_crlf = TRUE;
  }

  scratch_len = j;

  if (replacements > 0) {
    Curl_safefree(conn->uploadbuffer);
    conn->uploadbuffer = scratch;
    conn->uploadbuf = scratch;
    conn->uploadsize = scratch_len;
    conn->uploadleft = scratch_len;
  } else {
    Curl_safefree(scratch);
  }

  if (trailing_crlf) {
    conn->bits.crlf = TRUE;
  } else {
    conn->bits.crlf = FALSE;
  }

  return result;
}

CURLcode escape_eob_markers(struct connectdata *conn, ssize_t nread) {
  char *scratch = NULL;
  char *src = conn->uploadbuf;
  char *dst = NULL;
  size_t capacity = 0;
  size_t used = 0;
  CURLcode result = CURLE_OK;

  for (ssize_t i = 0; i < nread; ++i) {
    if (i > 0 && src[i - 1] == '\r' && src[i] == '\n') {
      if (used + 4 > capacity) {
        size_t new_capacity = capacity ? capacity * 2 : 16;
        if (new_capacity < used + 4) {
          new_capacity = used + 4;
        }
        char *new_scratch = realloc(scratch, new_capacity);
        if (!new_scratch) {
          result = CURLE_OUT_OF_MEMORY;
          goto cleanup;
        }
        scratch = new_scratch;
        capacity = new_capacity;
        dst = scratch;
      }
      dst = mempcpy(dst, src, i - (i - 1));
      dst = mempcpy(dst, "\r\n.", 3);
      i++;  // Skip the next character (we just consumed a CRLF)
    } else {
      if (used + 1 > capacity) {
        size_t new_capacity = capacity ? capacity * 2 : 16;
        if (new_capacity < used + 1) {
          new_capacity = used + 1;
        }
        char *new_scratch = realloc(scratch, new_capacity);
        if (!new_scratch) {
          result = CURLE_OUT_OF_MEMORY;
          goto cleanup;
        }
        scratch = new_scratch;
        capacity = new_capacity;
        dst = scratch;
      }
      *dst++ = src[i];
    }
  }

  if (scratch) {
    if (conn->uploadbuf) {
      free(conn->uploadbuf);
    }
    conn->uploadbuf = scratch;
    conn->upload_size = dst - scratch;
    conn->upload_left = conn->upload_size;
  }

cleanup:
  if (result != CURLE_OK) {
    free(scratch);
    conn->upload_size = nread;
    conn->upload_left = nread;
  }

  return result;
}

