  ssize_t i, j, eob_replaced = 0;
  unsigned char *src, *dst, *new_buffer;

  if (nread <= 0)
    return CURLE_OK;

  src = conn->upload.upload_from here;
  new_buffer = malloc(nread * 2 + 1); // worst-case expansion: CRLF -> CRLF.CRLF
  if (!new_buffer)
    return CURLE_OUT_OF_MEMORY;

  dst = new_buffer;
  for (i = 0; i < nread; i++) {
    if (i + 1 < nread && src[i] == '\r' && src[i + 1] == '\n') {
      // Found a CRLF
      *dst++ = src[i];
      *dst++ = src[i + 1];
      *dst++ = '.'; // Escape with a dot
      i++;          // Skip the next character
      eob_replaced++;
    } else {
      *dst++ = src[i];
    }
  }

  // Terminate the new buffer
  *dst = '\0';

  // Update the upload buffer
