    free(conn->upload.buffer);
  }

  conn->upload.buffer = new_buffer;
  conn->upload.size = dst - new_buffer;

  return CURLE_OK;
}

CURLcode escape_eob_smtp(struct connectdata *conn, ssize_t nread) {
  ssize_t i, j;
  char *scratch = NULL;
  size_t scratch_len = 0;
  size_t replacements = 0;
  CURLcode result = CURLE_OK;

  scratch_len = nread + 2; /* Allow space for up to two additional bytes */
  scratch = malloc(scratch_len);
  if (!scratch) {
    result = CURLE_OUT_OF_MEMORY;
    goto cleanup;
  }

  for (i = 0, j = 0; i < nread; ++i) {
    if (conn->upload_fromhere[i] == '\r' && i + 1 < nread && conn->upload_fromhere[i + 1] == '\n') {
      scratch[j++] = '.';
      scratch[j++] = '\r';
      scratch[j++] = '\n';
      i++; /* Skip the next '\n' since it's part of the CRLF pair */
      replacements++;
    } else {
      scratch[j++] = conn->upload_fromhere[i];
    }
  }

  if (replacements > 0) {
    /* Free the original upload buffer */
    free(conn->upload_buffer);

    /* Resize scratch to the actual needed size */
    scratch = realloc(scratch, j);
    if (!scratch) {
      result = CURLE_OUT_OF_MEMORY;
      goto cleanup;
    }

    conn->upload_buffer = scratch;
    conn->upload_left = j;
    conn->upload_fromhere = conn->upload_buffer;
  }

cleanup:
  if (result != CURLE_OK) {
    free(scratch);
  }

  return result;
}
